              By checking this box, you confirm that you have read and accept our full terms and conditions.
            </p>
            {error && (
              <p id="error-message" className="error-message" role="alert">
                Error: {error}
              </p>
            )}
          </div>

          <button type="submit">
            Continue
          </button>
        </form>
      </div>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
