const App = () => {
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState(null);
  const checkboxRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!agreed) {
      setError("You must agree to the terms of use before proceeding.");
      checkboxRef.current.focus();
    } else {
      setError(null);
      alert("Form submitted successfully!");
    }
  };

  return (
    <main>
      <div className="form-container">
        <h1>Welcome</h1>
        <p className="intro">Please review and accept our terms to continue.</p>

        <form onSubmit={handleSubmit} noValidate>
          <div className="form-field">
            <div className="checkbox-wrapper">
              <input
                type="checkbox"
                id="consent-checkbox"
                name="consent"
                required
                checked={agreed}
                onChange={(e) => {
                  setAgreed(e.target.checked);
                  if (e.target.checked) setError(null);
                }}
                ref={checkboxRef}
                aria-describedby={error ? "helper-text error-message" : "helper-text"}
                aria-invalid={!!error}
              />
              <label htmlFor="consent-checkbox" className="checkbox-label">
                I agree to the Terms of Use <span aria-hidden="true">*</span>
                <span className="visually-hidden">(Required)</span>
              </label>
            </div>
            <p id="helper-text" className="helper-text">
              By checking this box, you confirm that you have read and accept our full terms and conditions.
            </p>
            {error && (
              <p id="error-message" className="error-message" role="alert">
                Error: {error}
              </p>
            )}
          </div>

          <button type="submit">
            Continue
          </button>
        </form>
      </div>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
