const fs = require('fs');
const path = require('path');

async function runTest() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Need to serve the file or use setContent
  // Using setContent with the combined HTML might be tricky with external scripts/styles
  // Let's create a temporary standalone file for testing if needed, or just use a simple server
  // Actually, let's use a small express server or just setContent and mock the external files

  const html = fs.readFileSync('index.html', 'utf8');
  const css = fs.readFileSync('styles.css', 'utf8');
  const js = fs.readFileSync('app.js', 'utf8');

  // Injecting scripts and styles into setContent
  const fullHtml = html
    .replace('<link rel="stylesheet" href="styles.css">', `<style>${css}</style>`)
    .replace('<script type="text/babel" src="app.js"></script>', `<script type="text/babel">${js}</script>`);

  await page.setContent(fullHtml, { waitUntil: 'networkidle' });

  // Wait for React to render (Babel needs time)
  await page.waitForSelector('main', { timeout: 5000 });

  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
}

runTest().catch(err => {
  console.error(err);
  process.exit(1);
});
